 "content": "from collections import Counter


def transform(grid):
    # The recurring background/foreground marker is the most common nonzero
    # color; each marker color selects its corresponding 3x3 symbol.
    counts = Counter(v for row in grid for v in row if v != 0)
    marker = counts.most_common(1)[0][0]
    symbols = {
        1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
        2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
        3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
    }
    return [row[:] for row in symbols[marker]]
